#!/usr/bin/env python3
"""Render native-kit snapshots as honest browser previews and take screenshots."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
catalog=json.loads((ROOT/'catalog.json').read_text())
CSS='''
*{box-sizing:border-box}body{margin:0;background:#080d16;color:#dce5ef;font-family:ui-monospace,SFMono-Regular,Consolas,"Liberation Mono",monospace}#capture{width:960px;min-height:480px;background:#0c1420;padding:36px;border:1px solid #233044}.eyebrow{color:#67e8f9;font:12px/1.5 system-ui;letter-spacing:2px;font-weight:700}.meta{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.badge{font:11px system-ui;color:#fbbf24;border:1px solid #73581e;border-radius:20px;padding:7px 12px;background:#2a2112}.window{border:1px solid #2c3c50;border-radius:12px;background:#101c2c;overflow:hidden}.chrome{padding:17px 22px;background:#152235;border-bottom:1px solid #2c3c50;display:flex;gap:20px;align-items:center;font-size:13px}.dots{color:#70839d;letter-spacing:4px}.command{color:#a5b4fc}.pane{padding:24px;min-height:290px}.box{display:flex;min-width:0}.text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.65}.code{margin:0;background:#0b1421;border:1px solid #233247;border-radius:6px;padding:16px;color:#d3e0ef;font:13px/1.6 ui-monospace,SFMono-Regular,Consolas,"Liberation Mono",monospace;white-space:pre-wrap;overflow-wrap:anywhere}.button{display:inline-flex;align-self:flex-start;gap:8px;border:1px solid #36516e;border-radius:5px;padding:7px 12px;font:13px/1.5 ui-monospace,SFMono-Regular,Consolas,"Liberation Mono",monospace;color:#d5e8f5;background:#1a2d44;max-width:100%;white-space:pre-wrap;overflow-wrap:anywhere}.plain{padding:2px 0;border:0;background:transparent;color:#8bdbe7}.key{color:#a5b4fc}.input{background:#0c1624;border:1px solid #2d445e;border-radius:5px;padding:12px 14px;font-size:13px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere}.input b{color:#93c5fd}.input span{color:#d4deec}.input small{float:right;color:#7d92ac}.link{color:#93c5fd;font-size:13px;line-height:1.6;overflow-wrap:anywhere}.footer{font:12px/1.6 system-ui;color:#8da0b9;margin-top:20px}.footer strong{color:#b7c7da}.sep{height:1px;background:#203047;margin:20px 0}
'''
JS='''
const colors={cyan:'#67e8f9',green:'#86efac',yellow:'#fcd34d',red:'#fda4af'};
function render(n){
 if(typeof n==='string'){const t=document.createElement('span');t.textContent=n;return t}
 const p=n.props||{};let el=document.createElement('div');
 if(n.type==='Box'){el.className='box';el.style.flexDirection=p.flexDirection||'row';el.style.gap=(p.gap||p.columnGap||0)*12+'px';if(p.flexGrow)el.style.flexGrow=p.flexGrow;if(p.flexWrap)el.style.flexWrap=p.flexWrap;(n.children||[]).forEach(c=>el.append(render(c)))}
 else if(n.type==='Text'){el.className='text';el.textContent=(n.children||[]).join('');if(p.bold)el.style.fontWeight='700';if(p.color)el.style.color=colors[p.color]||p.color;if(p.dimColor)el.style.color='#92a3ba'}
 else if(n.type==='Code'){el=document.createElement('pre');el.className='code';el.textContent=p.source||''}
 else if(n.type==='Button'){el.className='button'+(p.plain?' plain':'');if(p.hotkey){const k=document.createElement('span');k.className='key';k.textContent=p.hotkey+':';el.append(k)}const label=document.createElement('span');label.textContent=p.label;el.append(label);if(p.dimColor)el.style.opacity='.65'}
 else if(n.type==='Input'){el.className='input';const label=document.createElement('b');label.textContent=(p.label||'Input')+': ';el.append(label);const value=document.createElement('span');value.textContent=p.value||p.placeholder||'';el.append(value);const hint=document.createElement('small');hint.textContent='↵ '+(p.submitLabel||'apply');el.append(hint)}
 else if(n.type==='Svg'){el=document.createElement('img');el.alt=p.alt;el.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(p.source);el.style.maxWidth='100%';el.style.height='auto'}
 else if(n.type==='Markdown'){el.className='text';el.textContent=p.text}
 else if(n.type==='Link'){el.className='link';el.textContent=(p.label?p.label+' · ':'')+p.href}
 else throw Error('Unsupported preview element '+n.type);
 return el
}
document.querySelector('.pane').append(render(DATA.tree));
'''
for i,m in enumerate(catalog):
 data=json.loads((ROOT/'assets/previews'/f"{m['id']}.json").read_text())
 if 'Unable to inspect' in str(data):raise RuntimeError(m['id']+' preview failed')
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{html.escape(m['title'])} · Mod preview</title><style>{CSS}</style></head><body><main id="capture"><div class="meta"><div class="eyebrow">AWESOME CLAUDE CODE MODS / {html.escape(m['category']).upper()}</div><span class="badge">FIXTURE PREVIEW · SAMPLE DATA</span></div><div class="window"><div class="chrome"><span class="dots">● ● ●</span><span class="command">/{html.escape(m['id'])}</span></div><div class="pane"></div></div><div class="footer"><strong>{i+1:02d} / {len(catalog)}</strong> · {html.escape(m['use'])}<div class="sep"></div>Captured from the mod's render tree by Claude Code 2.1.288's test kit.<br>Browser preview styling; native Terminal and Desktop painting may differ.</div></main><script>const DATA={json.dumps(data).replace('<',chr(92)+'u003c')};{JS}</script></body></html>'''
 (ROOT/'assets/previews'/f"{m['id']}.html").write_text(page)
print('Rendered',len(catalog),'preview pages')

# The gallery is static and runs from a local file or any static web host.
cards=''.join(f'''<a class="card" href="assets/previews/{m['id']}.html" data-category="{m['category']}" data-search="{html.escape((m['title']+' '+m['description']+' '+m['use']).lower(),quote=True)}"><img loading="lazy" src="assets/screenshots/{m['id']}.png" alt="{html.escape(m['title'])} fixture preview"><div class="info"><small>{m['category']}</small><h2>{m['title']}</h2><p>{m['description']}</p><code>/{m['id']}</code></div></a>''' for m in catalog)
gallery=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{len(catalog)} Awesome Claude Code Mods</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#080d16;color:#dce5ef;font:16px/1.6 system-ui}}main{{max-width:1380px;padding:48px 28px;margin:auto}}header{{max-width:760px}}.kicker{{color:#67e8f9;font-size:13px;letter-spacing:2px}}h1{{font-size:clamp(32px,6vw,64px);line-height:1.1;letter-spacing:-2px}}p{{color:#9dacc1}}.toolbar{{display:flex;gap:12px;flex-wrap:wrap;margin:32px 0 14px}}input,select{{background:#122033;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:12px 16px;font:inherit}}input{{flex:1;min-width:200px}}label{{position:absolute;clip:rect(0,0,0,0)}}#count{{color:#8da0b9;margin:14px 0}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:22px}}.card{{color:inherit;text-decoration:none;border:1px solid #24354b;border-radius:12px;background:#101c2c;overflow:hidden}}.card:hover{{border-color:#67e8f9}}.card img{{width:100%;aspect-ratio:1.55;object-fit:cover;object-position:top;display:block;border-bottom:1px solid #24354b}}.info{{padding:20px}}small{{color:#67e8f9}}h2{{font-size:21px;margin:8px 0}}.info p{{font-size:14px;min-height:44px}}code{{color:#a5b4fc;font-size:12px}}a:focus-visible,input:focus-visible,select:focus-visible{{outline:3px solid #67e8f9;outline-offset:3px}}footer{{margin-top:48px;color:#92a3ba;font-size:13px}}footer a{{color:#93c5fd}}</style></head><body><main><header><div class="kicker">OPEN SOURCE · MIT · NO RUNTIME PACKAGES</div><h1>Small mods.<br>Useful every day.</h1><p>{len(catalog)} independent tools for Claude Code, including 20 for the Desktop Code tab. Inspect your Git work, understand the session, keep project notes, or debug text without leaving your conversation.</p><p>These screenshots show native-kit render trees with fixture data, painted in a browser preview. They are not captures of the Claude Code app.</p></header><div class="toolbar"><label for="search">Search mods</label><input id="search" placeholder="Search use cases, tools, or names" type="search"><label for="category">Category</label><select id="category"><option value="">All categories</option>{''.join('<option>'+c+'</option>' for c in dict.fromkeys(m['category'] for m in catalog))}</select></div><p id="count" aria-live="polite"></p><div class="grid">{cards}</div><footer><a href="https://github.com/whyashthakker/awesome-claude-code-mods">Source and installation guide on GitHub</a> · Claude Code 2.1.287+ · Tested with 2.1.288</footer></main><script>const cards=[...document.querySelectorAll('.card')];function filter(){{const query=document.querySelector('#search').value.toLowerCase(),category=document.querySelector('#category').value;let n=0;for(const card of cards){{card.hidden=!(card.dataset.search.includes(query)&&(!category||card.dataset.category===category));if(!card.hidden)n++}}document.querySelector('#count').textContent=n+' of {len(catalog)} mods'}}document.querySelector('#search').addEventListener('input',filter);document.querySelector('#category').addEventListener('change',filter);filter()</script></body></html>'''
(ROOT/'gallery.html').write_text(gallery)
